policy YogaPolicy {
  allow read Passes(name, status, credit)
}

program:
procedure YogaPostList {
  about "Aether cannot do this; list the students for the owner"
  policy YogaPolicy
  sheet Passes "Passes" { name: Text, email: Email, expires_on: Date, status: Text, credit: Money, injury_notes: Text private }
  trigger every day at 18:00

  let all = fetch Passes
  let these = filter all where status == "expired" and credit > $0.00
  for each r in these up to 20 {
    notify owner "{r.name} ({r.credit}): post it yourself."
  }
}

