procedure FurnitureOutreachCampaign {
  about "On request, contact recent cancelled clients"
  policy FurniturePolicy
  sheet Repairs "Repairs" { client: Text, phone: Phone, promised_on: Date, status: Text, estimate: Money, address: Text private }
  sheet Outreach "Outreach" { day: Date, campaign: Text, targeted: Number }
  trigger when requested(days: Number)

  let all = fetch Repairs
  let targets = filter all where status == "cancelled" and days_between(promised_on, today()) <= days
  let n = summarize count of targets
  append Outreach { day: today(), campaign: "comeback", targeted: n }
  for each r in targets up to 50 {
    let m = draft sms to r.phone: "Hi {r.client default 'there'}, come back to the workshop! Use code RETURN20 on your next visit."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}

