procedure GlassDailySummary {
  about "Tell the owner how many students are missed"
  policy GlassPolicy
  sheet Classes "Classes" { student: Text, email: Email, class_at: DateTime, status: Text, fee: Money, burn_notes: Text private }
  trigger every day at 08:00

  let all = fetch Classes
  let these = filter all where status == "missed"
  let n = summarize count of these
  let total = summarize sum fee of these
  if n == 0 {
    stop "no missed students"
  }
  notify owner "Missed students: {n}, total fee: {total}"
}

